; ---- RAM work area, I/O and addresses outside this ROM ----
ZSVCCODE            = 0x7000  ; (F000H) service asked of the Z-80: 43H function in A, b5 call LHPC, b4 pass registers
ZSVCREQ             = 0x7001  ; (F001H) <> 0: the LH5803 asks the Z-80 for a service on return
LHMODE              = 0x7002  ; (F002H) CALLH mode: 30H call LHPC, 40H initialise, 41H peripheral interrupt, 43H power off, 44H USCNVL
LHPEND              = 0x7003  ; (F003H) FFH: no CALLH pending
LHREG_T             = 0x7004  ; (F004H) register image: flags (b4 H, b3 V, b2 Z, b1 IE, b0 C)
