LHPC_L              = 0x700C  ; (F00CH) CALLH start address, low byte
LHPC_H              = 0x700D  ; (F00DH) CALLH start address, high byte
LHPV                = 0x700E  ; (F00EH) b0: PV bank of the CALLH address
ISRFLG              = 0x7014  ; (F014H) b0: a peripheral interrupt routine is running (errors unwind to ISR_CALL)
S1DESC              = 0x7015  ; (F015H) slot S1 descriptor (page of the program area, b7 flag)
