DSPLPTR             = 0x705C  ; (F05CH) LCD display start line
MODMAP150           = 0x70B0  ; (F0B0H) PV=0 PC-1500 peripheral ROMs found (55H at B800H, AF00H, ... 8800H)
MODMAP150P          = 0x70B1  ; (F0B1H) the same for PV=1
