;------------------------------------------------------------------------------
; $C34F - Patch in GET_VAR_ADDR_1 ($D46A): only standard variables in MODE 0
; Replaces A04's ANI A,$A0 \ EOR (X).  A name whose second byte (A = UL) is not
; 00H / 20H, i.e. anything but A-Z / A$-Z$, is refused with error 110 (6EH) unless
; BMODE b6 (MODE 1) is set: in MODE 0 the PC-1500 commands run on the Z-80's
; variable storage, which the LH5803 reaches only for the standard variables.
;------------------------------------------------------------------------------
P_VARNAME:
	bii a,0xDF                      ; C34F  bfdf
	bzr P_VARNAME_1                 ; C351  8906
P_VARNAME_2:
	ani a,0xA0                      ; C353  b9a0
	eor (x)                         ; C355  0d
	jmp GET_VAR_ADDR_1_1            ; C356  bad46d       back into GET_VAR_ADDR_1
P_VARNAME_1:
	bii (BMODE),0x40                ; C359  ed71bc40
	bzr P_VARNAME_2                 ; C35D  990c         MODE 1: all names allowed
	pop a                           ; C35F  fd8a
	ldi uh,0x6E                     ; C361  686e         error 110
	jmp RTN_2_DA_1                  ; C363  badd01       error: branch through D2 of the caller
	.db 0x37, 0x1B, 0x8D, 0xC6, 0xE3, 0xF1, 0x78, 0xBC; C366               unused (fill)
	.db 0x5E, 0xAF, 0x57, 0x2B, 0x95, 0xCA, 0x65, 0xB2; C36E               ?? '^.W+..e.'
	.db 0x59, 0x2C, 0x16, 0x8B      ; C376  592c168b     ?? 'Y,..'



