;------------------------------------------------------------------------------
; $C394 - Split a banked BASIC pointer into bank index and address
; The PC-1600 keeps the BASIC program in up to five 16 KB banks (ADTBL); the top
; bits of a pointer select the bank: b7 = 0 -> 5, b7-6 = 11 -> 4, 10 -> 3.
;
;   Entry parameters: (7899)(789A) = the pointer (VEJ (CC) D1 = 99H)
; Modified registers: X-Reg = address (b7-6 cleared when b7 was set)
;                     A = UL = bank index
;   Error conditions: None
;------------------------------------------------------------------------------
P_BANKPTR:
	vej 0xCC                        ; C394  cc
	.db <VAR_START_H                ; C395  99
	lda xh                          ; C396  84
	ldi ul,0x05                     ; C397  6a05
	bii a,0x80                      ; C399  bf80
	bzs P_BANKPTR_2                 ; C39B  8b09
	dec ul                          ; C39D  62
	bii a,0x40                      ; C39E  bf40
	bzr P_BANKPTR_1                 ; C3A0  8901
	dec ul                          ; C3A2  62
P_BANKPTR_1:
	ani a,0x3F                      ; C3A3  b93f
	sta xh                          ; C3A5  08
P_BANKPTR_2:
	lda ul                          ; C3A6  24
	rtn                             ; C3A7  9a
	.db 0xCC, 0x66, 0xB3            ; C3A8  cc66b3       unused



