	bzs X_CHKTOK_3                  ; CDEE  8b2e
	ldi uh,0x5C                     ; CDF0  685c         sub-CPU command 5CH
	sjp SUBCMD                      ; CDF2  bee530
	nop                             ; CDF5  38
	nop                             ; CDF6  38
	bcs X_CHKTOK_ERR                ; CDF7  8323
	lda (TITLE)                     ; CDF9  a571d5       program area 0 = S0
	bzs X_CHKTOK_RUN                ; CDFC  8b12
	shr                             ; CDFE  d5
	bzs X_CHKTOK_1                  ; CDFF  8b05         TITLE 1 (S1) takes S2DESC and TITLE 2 takes S1DESC here, unmasked (the NEW revision: S1DESC for 1, S2DESC for 2, AND 7FH)
	lda (S1DESC)                    ; CE01  a57015
	bch X_CHKTOK_2                  ; CE04  8e03
