	vej 0xCC                        ; DFEE  cc
	.db <BASPRG_END_H               ; DFEF  67
	inc x                           ; DFF0  44
	bch STRBUF_2_ARX_3              ; DFF1  9e18



;------------------------------------------------------------------------------
; $DFF3 - U-Reg = STATUS 1-2. Program start after X-Reg; length according to U.
;------------------------------------------------------------------------------
STATUS_2_UREG:
	vmj 0x12                        ; DFF3  cd12



;------------------------------------------------------------------------------
; $DFF5 - (16) U-Reg = U-Reg - X-Reg. Determines the difference between
; the X-Reg and the end of the program memory (STATUS 1-2).
;------------------------------------------------------------------------------
STATUS_2_UREG_1:
	vej 0xF4                        ; DFF5  f4
	.dw BASPRG_END_H                ; DFF6  7867
	bch STRBUF_2_ARX_4              ; DFF8  9e19



;------------------------------------------------------------------------------
; $DFFA - (14) U-Reg = STATUS 1-2 . Loads X with program start, U with length.
;------------------------------------------------------------------------------
STATUS_1M2_UREG:
	vej 0xCC                        ; DFFA  cc
	.db <BASPRG_ST_H                ; DFFB  65
	bch STATUS_2_UREG_1             ; DFFC  9e09
	.db 0xE4, 0xE4                  ; DFFE  e4e4         unused (VEJ (E4) filler, as A04)



; ====================================================================
; PC-1600: THE LH5803 SIDE OF THE CALLH BRIDGE
; ====================================================================

;------------------------------------------------------------------------------
; $E000 - Reset: initialise the LH5803 side and enter the CALLH command loop
; The PC-1600 resets the LH5803 when the Z-80 asks for LHMODE 40H (P0-B0 0443H,
; at every power-on) and jumps here again for a later 40H.  With LHMODE = 40H the
; stack is set up and the PC-1500 peripherals are initialised (LH5810 image,
; module scan, LHINIT150).  A04: the PC-1500 reset / power-on at $E000.
;------------------------------------------------------------------------------
RESET:
	rie                             ; E000  fdbe
	ldi uh,0x96                     ; E002  6896
	ldi ul,0xFF                     ; E004  6aff
RESET_3:
	lop ul,RESET_3                  ; E006  8802         short settling delay
	ani (ISRFLG),0xFE               ; E008  e97014fe
	lda (LHMODE)                    ; E00C  a57002
	cpi a,0x40                      ; E00F  b740
	bzr LHIDLE                      ; E011  8906
	ldi s,0x781F                    ; E013  aa781f
	sjp LHINIT150                   ; E016  bee5c1



;------------------------------------------------------------------------------
; $E019 - Idle: nothing asked of the Z-80 (40H); hand the bus back and serve the next CALLH
;------------------------------------------------------------------------------
LHIDLE:
	ldi a,0x40                      ; E019  b540
	sta (ZSVCCODE)                  ; E01B  ae7000
	sjp LHDISPATCH                  ; E01E  bee093
	bch LHIDLE                      ; E021  9e0a



; ====================================================================
; Entry points for the Z-80 (CALLH mode 30H, LHPC = the address)
; ====================================================================

;------------------------------------------------------------------------------
; $E023 - (Z-80 EXCOMM1500 01ABH) Execute a PC-1500 command token
; Y-Reg = PROCPTR (the BASIC text pointer, b15 cleared), XL = BMODE.
; OLD revision: runs in the current banking; the NEW one maps the BASIC program
; bank first (P_MAPPRG) and restores P_BANK afterwards.
;------------------------------------------------------------------------------
X_EXCOMM:
	ldx s                           ; E023  fd48
	lda xh                          ; E025  84



;------------------------------------------------------------------------------
; $E026 - Save S-Reg for the return of X_EXCOMM (A = high byte, XL = low byte)
; S is kept in EXCSTK_H / EXCSTK_L; EXC_RET ($C418) restores it.
;------------------------------------------------------------------------------
X_EXCOMM_1:
	sta (EXCSTK_H)                  ; E026  ae73b6
	lda xl                          ; E029  04
	jmp X_CHKTOK                    ; E02A  bacddd



;------------------------------------------------------------------------------
; $E02D - (Z-80 FUNC 0202H) Evaluate a PC-1500 function
; The function token is in U-Reg (from DE), its argument in AR-X; VMJ ($1C) with
; D1 = 01H is the function-call routine of the interpreter.
;------------------------------------------------------------------------------
X_FUNC:
	vmj 0x1C                        ; E02D  cd1c
	.db 0x01                        ; E02F  01
	rtn                             ; E030  9a
	.db 0xB5, 0x80, 0xA5, 0x79, 0xD6; E031               unused (the NEW revision has X_SAVESTK here)



;------------------------------------------------------------------------------
; $E036 - Set S-Reg to (79D8)(A) and return: unwinds to the X_EXCOMM caller
;------------------------------------------------------------------------------
X_SETSTK:
	sta xl                          ; E036  0a
	lda (ISRSTK_H)                  ; E037  a579d8
	sta xh                          ; E03A  08
	stx s                           ; E03B  fd4e
	rtn                             ; E03D  9a



;------------------------------------------------------------------------------
; $E03E - Unwind an error in a peripheral interrupt routine: S-Reg from 79D8H/79D7H
; (saved by ISR_CALL), then return there
;------------------------------------------------------------------------------
X_ERRSTK:
	lda (ISRSTK_L)                  ; E03E  a579d7
	bch X_SETSTK                    ; E041  9e0d



;------------------------------------------------------------------------------
; $E043 - (Z-80 TOK1500 01A8H / FOTOK1500 01A5H) Look up a token of a PC-1500 peripheral
; U-Reg = the token (the Z-80's DE).  A = 1: TOK_PROCESS (VMJ ($1C), D1 = 04H);
; A = 0: an F0xxH token in the table of the attached peripheral (OPN >= 40H).
; On return A = 0: not found.
;------------------------------------------------------------------------------
X_TOKEN:
	jmp X_TOKEN_GO                  ; E043  bacd98
	.db 0x38                        ; E046  38           unused



;------------------------------------------------------------------------------
; $E047 - (Z-80 OPANDOR) Logical AND / OR of AR-X and AR-Y
; Both operands are converted to 16-bit integers (VEJ (D0)); the result is
; stored back into AR-X (7A05/7A06).
;
;   Entry parameters: AR-X, AR-Y = operands, YL = token low byte: 50H AND, 51H OR
; Modified registers: All registers, UH = 0
;   Error conditions: UH = error code (operand out of range)
;------------------------------------------------------------------------------
X_ANDOR:
	vej 0xD0                        ; E047  d0
	.db 0x04                        ; E048  04
	.db X_ANDOR_3-.-1               ; E049  28
	psh u                           ; E04A  fda8
	psh y                           ; E04C  fd98
	psh x                           ; E04E  fd88
	vmj 0x54                        ; E050  cd54
	vmj 0x56                        ; E052  cd56
	pop x                           ; E054  fd0a
	pop y                           ; E056  fd1a
	vej 0xD0                        ; E058  d0
	.db 0x04                        ; E059  04
	.db X_ANDOR_4-.-1               ; E05A  18
	pop u                           ; E05B  fd2a
	ldi xl,0x06                     ; E05D  4a06
	ldi xh,0x7A                     ; E05F  487a
	lda ul                          ; E061  24
	dec yl                          ; E062  52
	bhs X_ANDOR_1                   ; E063  8706
	and (x)                         ; E065  09
	sde x                           ; E066  43
	lda uh                          ; E067  a4
	and (x)                         ; E068  09
	bch X_ANDOR_2                   ; E069  8e04
X_ANDOR_1:
	ora (x)                         ; E06B  0b
	sde x                           ; E06C  43
	lda uh                          ; E06D  a4
	ora (x)                         ; E06E  0b
X_ANDOR_2:
	sta (x)                         ; E06F  0e
	ldi uh,0x00                     ; E070  6800
X_ANDOR_3:
	rtn                             ; E072  9a
X_ANDOR_4:
	pop x                           ; E073  fd0a
	rtn                             ; E075  9a



;------------------------------------------------------------------------------
; $E076 - USCNVL (LHMODE 44H): format AR-X with the current USING
; Called by the Z-80's USCNVL_B3 ($5D56) with the format in LHREG_UH.
;
;   Entry parameters: AR-X = number, LHREG_UH = USING format byte
; Modified registers: LHREG_XH/XL = address of the text, Z-80 view (b15 set)
;                     LHREG_A = length; 0 and Carry=1 if AR-X is a string or the
;                     number does not fit
;------------------------------------------------------------------------------
USCNVL:
	vej 0xD2                        ; E076  d2
	.db USCNVL_1-.-1                ; E077  08
	.db 0x80                        ; E078  80
	lda (LHREG_UH)                  ; E079  a5700b
	vmj 0x96                        ; E07C  cd96
	bcr USCNVL_2                    ; E07E  8103
USCNVL_1:
	sec                             ; E080  fb
	ldi a,0x00                      ; E081  b500
USCNVL_2:
	sta (LHREG_A)                   ; E083  ae7005
	lda xh                          ; E086  84
	ori a,0x80                      ; E087  bb80
	sta (LHREG_XH)                  ; E089  ae7007
	lda xl                          ; E08C  04
	sta (LHREG_XL)                  ; E08D  ae7006
USCNVL_3:
	rtn                             ; E090  9a
	.db 0x94                        ; E091  94           unused



;------------------------------------------------------------------------------
; $E092 - Stub of the vectors of removed functions: (5A) clock mode (PD1990AC), (9A)
; USING execution, (9C) display of AR-X.
; OLD revision: the byte is 4AH, i.e. LDI XL,$A5 with the first byte of
; LHDISPATCH as its operand, so these vectors run on out of step (70H 00H ...).
; The NEW revision has 04H (LDA XL) and falls into LHDISPATCH.
;------------------------------------------------------------------------------
VEC_REMOVED:
	.db 0x4A                        ; E092  4a



;------------------------------------------------------------------------------
; $E093 - Dispatch ZSVCCODE: idle (40H), a service of the Z-80 (b6 / b5), or the end of a
; CALLH (b6 = b5 = 0), then hand the bus to the Z-80 and serve the next CALLH
; An LH5803 routine that needs the Z-80 sets ZSVCCODE and calls here; it
; continues when the Z-80 answers with LHPEND = 0.
;------------------------------------------------------------------------------
LHDISPATCH:
	lda (ZSVCCODE)                  ; E093  a57000
	cpi a,0x40                      ; E096  b740
	bzs LHDONE                      ; E098  8b56
	bii a,0x40                      ; E09A  bf40
	bzr LHDISPATCH_1                ; E09C  8907
	bii a,0x20                      ; E09E  bf20
	bzr LHDISPATCH_1                ; E0A0  8903
	jmp LHSVCEND                    ; E0A2  bae210
LHDISPATCH_1:
	ori (ZSVCREQ),0xFF              ; E0A5  eb7001ff     ask the Z-80 for a service



;------------------------------------------------------------------------------
; $E0A9 - Hand the bus to the Z-80; execution resumes here at the next CALLH
;------------------------------------------------------------------------------
LHYIELD:
	sta #(P_CPUSW)                  ; E0A9  fdaea038     port 38H: switch to the Z-80
	nop                             ; E0AD  38
	bii (LHPEND),0xFF               ; E0AE  ed7003ff     LHPEND = 0: the service asked for is done
	bzs USCNVL_3                    ; E0B2  9b24
	lda (LHMODE)                    ; E0B4  a57002       new CALLH: dispatch on LHMODE
	bii a,0x40                      ; E0B7  bf40
	bzs LHCALL                      ; E0B9  8bdf         20H / 30H: call LHPC
	cpi a,0x41                      ; E0BB  b741
	bzs LHDONE                      ; E0BD  8b31         41H: peripheral interrupt (served with interrupts enabled)
	cpi a,0x44                      ; E0BF  b744
	bzr LHYIELD_1                   ; E0C1  8903
	jmp LHUSCNVL                    ; E0C3  bae231       44H: USCNVL
LHYIELD_1:
	cpi a,0x40                      ; E0C6  b740
	bzs LHYIELD_2                   ; E0C8  8b0a         40H: reset
	cpi a,0x42                      ; E0CA  b742
	bzs LHSETSTK                    ; E0CC  8b5e         42H: continue with S-Reg = LHPC
	cpi a,0x43                      ; E0CE  b743
	bzs LHPOWER                     ; E0D0  8b07         43H: power function A
	bch LHDONE                      ; E0D2  8e1c
LHYIELD_2:
	jmp RESET                       ; E0D4  bae000
	.db 0x8E, 0x17                  ; E0D7  8e17         unused



;------------------------------------------------------------------------------
; $E0D9 - LHMODE 43H: power function LHREG_A (as the Z-80's TIMER / COM IOCS 0 does)
; 0 = cold start, 1 = power on, 2 = power on after auto power-off, 3 = power off,
; 4 = auto power-off (the LH5803 state is kept: 79D9H = 55H, S-Reg in 73B7H/73B8H).
;------------------------------------------------------------------------------
LHPOWER:
	lda (LHREG_A)                   ; E0D9  a57005
	cpi a,0x00                      ; E0DC  b700
	bzs LHPOWER_0                   ; E0DE  8b59
	cpi a,0x01                      ; E0E0  b701
	bzs LHPOWER_1                   ; E0E2  8bb2
	cpi a,0x02                      ; E0E4  b702
	bzs LHPOWER_2                   ; E0E6  8b0e
	cpi a,0x03                      ; E0E8  b703
	bzs LHPOWER_3                   ; E0EA  8b28
	cpi a,0x04                      ; E0EC  b704
	bzs LHPOWER_4                   ; E0EE  8b28
LHDONE:
	ani (ZSVCREQ),0x00              ; E0F0  e9700100
	bch LHYIELD                     ; E0F4  9e4d



;------------------------------------------------------------------------------
; $E0F6 - 2: power on after auto power-off: resume the saved LH5803 state if there is one
;------------------------------------------------------------------------------
LHPOWER_2:
	lda (APOVALID)                  ; E0F6  a579d9
	cpi a,0x55                      ; E0F9  b755
	bzr LHPOWER_2_1                 ; E0FB  8911
	lda (APOSTK_H)                  ; E0FD  a573b8
	sta xh                          ; E100  08
	lda (APOSTK_L)                  ; E101  a573b7
	sta xl                          ; E104  0a
	stx s                           ; E105  fd4e
	ldi a,0x01                      ; E107  b501
	sta (ARV)                       ; E109  ae7a20
	bch LHPOWER_0_2                 ; E10C  8e4d
LHPOWER_2_1:
	ori (0x7A21),0x80               ; E10E  eb7a2180
	bch LHPOWER_END                 ; E112  8e69



;------------------------------------------------------------------------------
; $E114 - 3: power off
;------------------------------------------------------------------------------
LHPOWER_3:
	ldi a,0x00                      ; E114  b500
	bch LHPOWER_4_1                 ; E116  8e0c



;------------------------------------------------------------------------------
; $E118 - 4: auto power-off: keep S-Reg (73B7H/73B8H) and mark it valid (79D9H = 55H)
;------------------------------------------------------------------------------
LHPOWER_4:
	ldx s                           ; E118  fd48
	lda xl                          ; E11A  04
	sta (APOSTK_L)                  ; E11B  ae73b7
	lda xh                          ; E11E  84
	sta (APOSTK_H)                  ; E11F  ae73b8
	ldi a,0x55                      ; E122  b555
LHPOWER_4_1:
	sta (APOVALID)                  ; E124  ae79d9
	sjp SUB_POFF                    ; E127  bee527
	bch LHDONE                      ; E12A  9e3c



;------------------------------------------------------------------------------
; $E12C - 42H: continue at LHPC with S-Reg = LHPC
;------------------------------------------------------------------------------
LHSETSTK:
	lda (LHPC_L)                    ; E12C  a5700c
	sta xl                          ; E12F  0a
	lda (LHPC_H)                    ; E130  a5700d
	sta xh                          ; E133  08
	stx s                           ; E134  fd4e
LHSETSTK_1:
	jmp LHIDLE                      ; E136  bae019



;------------------------------------------------------------------------------
; $E139 - 0: cold start (ARV := 2); 1: power on (ARV := 0)
; Stack, cursor, katakana (KATAFLAGS := FFH, KATACHAR := C7H) and 79D2H-79DDH
; are initialised.  If VMJ ($BE) finds a CE-150 / CE-158 (Carry=1), the
; initialisation entry XH:0AH of its ROM is called with A = the function.
;------------------------------------------------------------------------------
LHPOWER_0:
	ldi a,0x02                      ; E139  b502
LHPOWER_0_1:
	sta (ARV)                       ; E13B  ae7a20
	ldi s,LHSTACK                   ; E13E  aa73af
	ani (CURS_CTRL),0x01            ; E141  e97b0e01
	ani (KATAFLAGS),0x00            ; E145  e9785d00     KATAFLAGS := $00 (the NEW revision: $FF, for the built-in katakana)
	ldi a,0xC7                      ; E149  b5c7         built-in katakana, see $C50C
	sta (KATACHAR)                  ; E14B  ae785e
	sjp BCMD_PI                     ; E14E  bef5b5
	vmj 0x5C                        ; E151  cd5c
	ldi xh,0x79                     ; E153  4879
	ldi xl,0xD2                     ; E155  4ad2
	ldi ul,0x0C                     ; E157  6a0c
	vmj 0xBA                        ; E159  cdba
LHPOWER_0_2:
	ori (CURS_CTRL),0x01            ; E15B  eb7b0e01
	vmj 0xBE                        ; E15F  cdbe
	bcr LHPOWER_END                 ; E161  811a
LHPOWER_0_3:
	psh a                           ; E163  fdc8
	psh x                           ; E165  fd88
	psh u                           ; E167  fda8
	ldi xl,0x0A                     ; E169  4a0a
	ldi uh,0xE1                     ; E16B  68e1         return here from the peripheral
	ldi ul,0x73                     ; E16D  6a73
	psh u                           ; E16F  fda8
	stx p                           ; E171  fd5e



;------------------------------------------------------------------------------
; $E173 - Return point of the peripheral initialisation
;------------------------------------------------------------------------------
LHPOWER_PRET:
	pop u                           ; E173  fd2a
	pop x                           ; E175  fd0a
	pop a                           ; E177  fd8a
	vmj 0xBC                        ; E179  cdbc
	bcs LHPOWER_0_3                 ; E17B  931a
LHPOWER_END:
	ani (APOVALID),0x00             ; E17D  e979d900
RESET_20:
	ori #(PC1500_MSK_REG),0x01      ; E181  fdebf00a01   enable the PC-1500 and CE-150 interrupts
	ori #(CE150_MSK_REG),0x01       ; E186  fdebb00a01
	sie                             ; E18B  fd81
	lda (LHREG_A)                   ; E18D  a57005
	cpi a,0x02                      ; E190  b702
	bzs LHDONE                      ; E192  9ba4
	bch LHSETSTK_1                  ; E194  9e60
LHPOWER_1:
	ldi a,0x00                      ; E196  b500
	bch LHPOWER_0_1                 ; E198  9e5f



;------------------------------------------------------------------------------
; $E19A - LHMODE 20H / 30H: call LHPC
; PV is set from LHPV, with 30H the registers are loaded from the register
; image; LHPC is entered through RTN, and it returns to LHCALLRET.
;------------------------------------------------------------------------------
LHCALL:
	ori (ZSVCREQ),0xFF              ; E19A  eb7001ff
	bii a,0x20                      ; E19E  bf20
	bzs LHCALL_1                    ; E1A0  8b08
	psh a                           ; E1A2  fdc8
	ldi xh,0xE1                     ; E1A4  48e1         return address LHCALLRET
	ldi xl,0xD0                     ; E1A6  4ad0
	psh x                           ; E1A8  fd88
LHCALL_1:
	ldi xh,0x70                     ; E1AA  4870
	ldi xl,0x0C                     ; E1AC  4a0c
	lin x                           ; E1AE  45
	psh a                           ; E1AF  fdc8
	lde x                           ; E1B1  47
	psh a                           ; E1B2  fdc8
	dec x                           ; E1B4  46
	sjp LHSETPV                     ; E1B5  bee21a       PV := LHPV
	bii (LHMODE),0x10               ; E1B8  ed700210     30H: registers from the image
	bzs LHCALL_2                    ; E1BC  8b11
	lde x                           ; E1BE  47
	sta uh                          ; E1BF  28
	lde x                           ; E1C0  47
	sta ul                          ; E1C1  2a
	lde x                           ; E1C2  47
	sta yh                          ; E1C3  18
	lde x                           ; E1C4  47
	sta yl                          ; E1C5  1a
	lde x                           ; E1C6  47
	sta xh                          ; E1C7  08
	lda (LHREG_XL)                  ; E1C8  a57006
	sta xl                          ; E1CB  0a
	lda (LHREG_A)                   ; E1CC  a57005
LHCALL_2:
	rtn                             ; E1CF  9a           enter LHPC



;------------------------------------------------------------------------------
; $E1D0 - Return from an LHPC call: store A, flags and (30H) X, Y, U into the image
;------------------------------------------------------------------------------
LHCALLRET:
	sta (LHREG_A)                   ; E1D0  ae7005
	psh x                           ; E1D3  fd88
	ldi xl,0x04                     ; E1D5  4a04
	bzs LHCALLRET_1                 ; E1D7  8b02
	ldi xl,0x00                     ; E1D9  4a00
LHCALLRET_1:
	tta                             ; E1DB  fdaa
	ani a,0xFB                      ; E1DD  b9fb
	rec                             ; E1DF  f9
	adc xl                          ; E1E0  02
	sta (LHREG_T)                   ; E1E1  ae7004
	pop x                           ; E1E4  fd0a
	pop a                           ; E1E6  fd8a
	sta (LHMODE)                    ; E1E8  ae7002
	bii (LHMODE),0x10               ; E1EB  ed700210
	bzs LHDONE_1                    ; E1EF  8b18
	lda xh                          ; E1F1  84
	sta (LHREG_XH)                  ; E1F2  ae7007
	lda xl                          ; E1F5  04
	sta (LHREG_XL)                  ; E1F6  ae7006
	lda yh                          ; E1F9  94
	sta (LHREG_YH)                  ; E1FA  ae7009
	lda yl                          ; E1FD  14
	sta (LHREG_YL)                  ; E1FE  ae7008
	lda uh                          ; E201  a4
	sta (LHREG_UH)                  ; E202  ae700b
	lda ul                          ; E205  24
	sta (LHREG_UL)                  ; E206  ae700a



;------------------------------------------------------------------------------
; $E209 - Service done: clear ZSVCREQ and wait for the next CALLH
;------------------------------------------------------------------------------
LHDONE_1:
	ani (ZSVCREQ),0x00              ; E209  e9700100
LHDONE_1_1:
	jmp LHYIELD                     ; E20D  bae0a9



;------------------------------------------------------------------------------
; $E210 - End of a Z-80 service request: ZSVCREQ := ZSVCCODE
;------------------------------------------------------------------------------
LHSVCEND:
	pop x                           ; E210  fd0a
	lda (ZSVCCODE)                  ; E212  a57000
	sta (ZSVCREQ)                   ; E215  ae7001
	bch LHDONE_1_1                  ; E218  9e0d



;------------------------------------------------------------------------------
; $E21A - Set PV from LHPV (interrupts off, flags preserved)
;------------------------------------------------------------------------------
LHSETPV:
	tta                             ; E21A  fdaa
	rie                             ; E21C  fdbe
	ani (PU_PV),0xFE                ; E21E  e979d0fe
	rpv                             ; E222  b8
	bii (LHPV),0x01                 ; E223  ed700e01
	bzs LHSETPV_1                   ; E227  8b05
	ori (PU_PV),0x01                ; E229  eb79d001
	spv                             ; E22D  a8
LHSETPV_1:
	att                             ; E22E  fdec
	rtn                             ; E230  9a



;------------------------------------------------------------------------------
; $E231 - LHMODE 44H: USCNVL, when LHREG_A = 0
;------------------------------------------------------------------------------
LHUSCNVL:
	lda (LHREG_A)                   ; E231  a57005
	cpi a,0x00                      ; E234  b700
	bzr LHDONE_1                    ; E236  992f
	sjp USCNVL                      ; E238  bee076
	bch LHDONE_1                    ; E23B  9e34



;------------------------------------------------------------------------------
; $E23D - Waits until no more keys are pressed
;------------------------------------------------------------------------------
WAITNOKEYS:
	ori (CURS_CTRL),0x03            ; E23D  eb7b0e03
	bch WAIT_4_KB_2                 ; E241  8e0b



;------------------------------------------------------------------------------
; $E243 - Entering a Character Using the Keyboard (Page 324:Keyboard Status)
; Waiting for input from keyboard. Character is in accumulator
; PC-1600: at auto power-off the Z-80 switches off (AUTO_OFF).
;------------------------------------------------------------------------------
WAIT_4_KB:
	lda (0x79D4)                    ; E243  a579d4
WAIT_4_KB_1:
	cpi a,0x55                      ; E246  b755
	bzs WAIT_4_KB_8                 ; E248  8b6d
	ani (CURS_CTRL),0xFD            ; E24A  e97b0efd
WAIT_4_KB_2:
	ldi xh,0x7B                     ; E24E  487b
	bii (CURS_CTRL),0x40            ; E250  ed7b0e40
	bzr WAIT_4_KB_3                 ; E254  8905
