;------------------------------------------------------------------------------
; $E530 - Send a command to the sub-CPU and wait for its answer
; Through the TC8576 parallel port (ME1 #(00xxH) is Z-80 port xxH, as #(A0xxH)).
; Command 15H (power off) halts the LH5803 instead of reading an answer.
;
;   Entry parameters: UH = command
; Modified registers: A = answer (P_SUBDAT >> 3), UL
;   Error conditions: Carry=1: no answer (timeout)
;------------------------------------------------------------------------------
SUBCMD:
	rie                             ; E530  fdbe
	ldi a,0x00                      ; E532  b500
	sta #(P_MOD)                    ; E534  fdaea030     P_MOD := 0
SUBCMD_1:
	bii #(P_CPCSEL),0x20            ; E538  fded002320
	bzr SUBCMD_1                    ; E53D  9907
	lda uh                          ; E53F  a4
	sta #(P_CPCPAR)                 ; E540  fdae0021
	ldi ul,0xFF                     ; E544  6aff
	ldi a,0x00                      ; E546  b500
SUBCMD_2:
	bii #(P_CPCSEL),0x40            ; E548  fded002340
	bzr SUBCMD_6                    ; E54D  8918
	cpi uh,0x15                     ; E54F  6c15
	bzr SUBCMD_5                    ; E551  890b
	hlt                             ; E553  fdb1         command 15H: sleep until power on
SUBCMD_3:
	ldi a,0x01                      ; E555  b501
	sta #(P_MOD)                    ; E557  fdaea030     P_MOD := 1
	sie                             ; E55B  fd81
SUBCMD_4:
	rtn                             ; E55D  9a
SUBCMD_5:
	lda #(P_SUBDAT)                 ; E55E  fda50033
	shr                             ; E562  d5
	shr                             ; E563  d5
	shr                             ; E564  d5
	bch SUBCMD_3                    ; E565  9e12
SUBCMD_6:
	dec a                           ; E567  df
	bzr SUBCMD_2                    ; E568  9922
	lop ul,SUBCMD_2                 ; E56A  8824
	sec                             ; E56C  fb
	bch SUBCMD_3                    ; E56D  9e1a
	.db 0x0C, 0x06, 0x83, 0xC1, 0x60, 0xB0, 0xD8, 0xEC; E56F               unused (fill)
	.db 0x76, 0xBB, 0xDD, 0xEE, 0xF7, 0x7B, 0xBD, 0xDE; E577               ?? 'v....{..'
	.db 0xEF, 0x77, 0x3B, 0x9D, 0xCE, 0xE7, 0x73, 0xB9; E57F               ?? '.w;...s.'
	.db 0x5C, 0x2E                  ; E587  5c2e         ?? '\.'



;------------------------------------------------------------------------------
; $E589 - Ask the Z-80 for service 43H (function in LHREG_A)
; Z-80 functions (bank 3 ZSVCFUNC $5C82): 3 POFF, 4 PAOFF, 10H TIMER IOCS with
; C = LHREG_UL and HL = FA02H (AR-X), 11H evaluate an expression.  X-Reg and
; Y-Reg are preserved.
;------------------------------------------------------------------------------
ZSVC43:
	ldi a,0x43                      ; E589  b543
	sta (ZSVCCODE)                  ; E58B  ae7000
