;------------------------------------------------------------------------------
; $E5A6 - TIME: read the clock into AR-X (TIMER IOCS 03H SRRT on the Z-80)
;------------------------------------------------------------------------------
TIME_READ:
	ldi a,0x03                      ; E5A6  b503
	sjp ZSVC_TIMER                  ; E5A8  bee5b6
	lda (0x7A02)                    ; E5AB  a57a02
	aex                             ; E5AE  f1
	sta (0x7A02)                    ; E5AF  ae7a02
	rtn                             ; E5B2  9a
	.db 0x38                        ; E5B3  38           unused
TIME_READ_1:
