	cpa (x)                         ; E600  07
	bzs LHINIT150_4                 ; E601  8b01
	rec                             ; E603  f9
LHINIT150_4:
	lda yh                          ; E604  94
	rol                             ; E605  db
	sta yh                          ; E606  18
	lda yl                          ; E607  14
	rol                             ; E608  db
	sta yl                          ; E609  1a
	cpi xh,0x88                     ; E60A  4c88
	bcr LHINIT150_5                 ; E60C  8106
	lda xh                          ; E60E  84
	adi a,0xF7                      ; E60F  b3f7
