;------------------------------------------------------------------------------
; $E6A5 - (F8) Maskable interrupt
; The cause comes from the SC7852 (P_INT, masked with P_LHMSK2):
;   b0  the Z-80 has an interrupt of its own: the CALLH state (7000H-7003H) is
;       saved and the bus handed back with ZSVCCODE = 41H until the Z-80 is done
;   b2  a PC-1500 peripheral (IRQ): as A04's ISR_HANDLER ($E171), the CE-158
;       interrupt register selects a peripheral ROM with the 55H mark at B000H,
;       9F00H, 8E00H (PV=0, then PV=1) whose entry at XX13H is called; CE-150
;       interrupts set CALLHFLG b0.  A user routine is called through 79DBH/79DCH
;       (b0 of 79DCH = PV) when 79DAH = 55H.
;------------------------------------------------------------------------------
ISR_HANDLER:
	psh a                           ; E6A5  fdc8
	psh x                           ; E6A7  fd88
	psh y                           ; E6A9  fd98
	psh u                           ; E6AB  fda8
