	ani a,0x05                      ; E6BD  b905
	and #(P_LHMSK2)                 ; E6BF  fda9a034
	ani (ISRFLG),0xFE               ; E6C3  e97014fe
	bii a,0x01                      ; E6C7  bf01
	bzs ISR_HANDLER_2               ; E6C9  8b46
	psh a                           ; E6CB  fdc8
	lda #(P_LHMSK2)                 ; E6CD  fda5a034     mask the PC-1500 interrupt while the Z-80 runs
	psh a                           ; E6D1  fdc8
	ani a,0xFB                      ; E6D3  b9fb
	sta #(P_LHMSK2)                 ; E6D5  fdaea034
	lda (ZSVCCODE)                  ; E6D9  a57000
	psh a                           ; E6DC  fdc8
	lda (ZSVCREQ)                   ; E6DE  a57001
	psh a                           ; E6E1  fdc8
	lda (LHMODE)                    ; E6E3  a57002
	psh a                           ; E6E6  fdc8
	lda (LHPEND)                    ; E6E8  a57003
	psh a                           ; E6EB  fdc8
	ldi a,0x41                      ; E6ED  b541         let the Z-80 serve its interrupt
	sta (ZSVCCODE)                  ; E6EF  ae7000
	sjp LHDISPATCH                  ; E6F2  bee093
	pop a                           ; E6F5  fd8a
	sta (LHPEND)                    ; E6F7  ae7003
	pop a                           ; E6FA  fd8a
	sta (LHMODE)                    ; E6FC  ae7002
	pop a                           ; E6FF  fd8a
	sta (ZSVCREQ)                   ; E701  ae7001
	pop a                           ; E704  fd8a
	sta (ZSVCCODE)                  ; E706  ae7000
	pop a                           ; E709  fd8a
	sta #(P_LHMSK2)                 ; E70B  fdaea034
	pop a                           ; E70F  fd8a
ISR_HANDLER_2:
	bii a,0x04                      ; E711  bf04
	bzs ISR_HANDLER_END             ; E713  8ba6
	bii #(PC1500_IF_REG),0x01       ; E715  fdedf00b01
	bzs ISR_USER                    ; E71A  8b69
	ani #(PC1500_MSK_REG),0xFE      ; E71C  fde9f00afe
	ani #(CE150_MSK_REG),0xFE       ; E721  fde9b00afe
	lda #(CE158_IR_REG)             ; E726  fda5de00
	ani #(CE150_IF_REG),0xFE        ; E72A  fde9b00bfe
	sta #(CE158_IR_PING)            ; E72F  fdaedc00
	eai a,0xFF                      ; E733  bdff
	bzs ISR_CE150                   ; E735  8b2e
ISR_HANDLER_PV:
	rpv                             ; E737  b8
ISR_HANDLER_3:
	ldi xh,0xB0                     ; E738  48b0
	ldi xl,0x00                     ; E73A  4a00
ISR_HANDLER_4:
