	shr                             ; E73E  d5
	psh a                           ; E73F  fdc8
	bcr ISR_HANDLER_NEXT            ; E741  810d
	ldi a,0x55                      ; E743  b555
	cpa (x)                         ; E745  07
	bzr ISR_HANDLER_NEXT            ; E746  8908
	ldi uh,0xE7                     ; E748  68e7         return address ISR_HANDLER_NEXT
	ldi ul,0x50                     ; E74A  6a50
	ldi xl,0x13                     ; E74C  4a13
	bch ISR_CALL                    ; E74E  8e59
ISR_HANDLER_NEXT:
