	cpi xh,0x90                     ; E756  4c90
	bcr ISR_HANDLER_5               ; E758  8108
	sta yl                          ; E75A  1a
	ldi a,0xEF                      ; E75B  b5ef
	adc xh                          ; E75D  82
	sta xh                          ; E75E  08
	lda yl                          ; E75F  14
	bch ISR_HANDLER_4               ; E760  9e26
ISR_HANDLER_5:
