	psh u                           ; E7E5  fda8
	psh y                           ; E7E7  fd98
	lda xl                          ; E7E9  04
	shr                             ; E7EA  d5
	cpi xh,0x76                     ; E7EB  4c76
	bcs LCD1500_BYTE_9              ; E7ED  8343
	cpi xh,0x75                     ; E7EF  4c75
